INSERT INTO `cohorts` (`id`, `programme_id`, `name`, `description`, `start_date`, `end_date`, `application_open_date`, `application_close_date`, `max_capacity`, `applications_count`, `location`, `province`, `delivery_mode`, `status`, `created_by`, `supervisor_id`, `programme_manager_id`, `programme_officer_id`, `created_at`, `updated_at`) VALUES
(1, 1, 'Software Development Programme - Pretoria', 'This cohort is designed for aspiring software developers who are looking to strengthen their technical skills through practical, project-based learning. Participants will gain hands-on experience in developing and maintaining web applications while working with technologies such as HTML, CSS, JavaScript, PHP, and MySQL.\r\nThroughout the programme, participants will work on real-world development tasks, practise database management, use Git for version control, and apply software development principles including debugging, testing, problem-solving, and secure coding practices. The cohort also focuses on professional development, teamwork, communication, and preparing participants for successful careers in the technology industry.', '2026-09-07', '2028-08-31', '2026-08-03', '2026-08-14', 15, 0, 'Pretoria', 'gauteng', 'hybrid', 'active', 1, NULL, NULL, NULL, '2026-08-08 16:49:09', '2026-08-12 07:15:57'),
(2, 4, '2026 Software Development Cohort', 'This cohort is designed for aspiring software developers who are looking to strengthen their technical skills through practical, project-based learning. Participants will gain hands-on experience in developing and maintaining web applications while working with technologies such as HTML, CSS, JavaScript, PHP, and MySQL.\r\nThroughout the programme, participants will work on real-world development tasks, practise database management, use Git for version control, and apply software development principles including debugging, testing, problem-solving, and secure coding practices. The cohort also focuses on professional development, teamwork, communication, and preparing participants for successful careers in the technology industry.', '2026-09-07', '2028-09-29', '2026-08-03', '2026-08-14', 10, 0, 'Pretoria', 'gauteng', 'hybrid', 'draft', 1, NULL, NULL, NULL, '2026-08-08 17:14:40', '2026-08-08 17:14:40'),
(4, 2, '2026/2027 IT Support & Technical Services Intake', 'This cohort is designed for recent IT graduates and aspiring technology professionals seeking practical workplace experience and professional development. Participants will gain hands-on exposure to areas such as software development, IT support, databases, networking, cybersecurity, and general technical services. Through structured training, mentorship, practical projects, and workplace activities, participants will have the opportunity to apply their academic knowledge in real-world environments while developing technical, problem-solving, communication, and teamwork skills. The programme aims to prepare participants for successful careers in the technology industry by providing practical experience and continuous professional development.', '2026-09-07', '2027-08-31', '2026-08-03', '2026-08-14', 12, 0, 'Pretoria', 'gauteng', 'on_site', 'active', 1, NULL, NULL, NULL, '2026-08-09 16:18:54', '2026-08-09 19:41:12'),
(5, 1, 'Software Development Programme - Mbombela', 'This cohort is designed for aspiring software developers who are looking to strengthen their technical skills through practical, project-based learning. Participants will gain hands-on experience in developing and maintaining web applications while working with technologies such as HTML, CSS, JavaScript, PHP, and MySQL.\r\n\r\nThroughout the programme, participants will work on real-world development tasks, practise database management, use Git for version control, and apply software development principles including debugging, testing, problem-solving, and secure coding practices. The cohort also focuses on professional development, teamwork, communication, and preparing participants for successful careers in the technology industry.', '2026-09-07', '2028-08-31', '2026-08-03', '2026-08-14', 10, 0, 'Mbombela', 'mpumalanga', 'hybrid', 'active', 1, NULL, NULL, NULL, '2026-08-09 19:17:13', '2026-08-09 19:20:42'),
(6, 3, '2027 Software Development WIL Programme Intake', '2027 Software Development WIL Programme Intake is designed to provide students with practical, hands-on experience in software development within a professional working environment. The cohort focuses on applying academic knowledge to real-world projects while developing technical, problem-solving, teamwork, and professional skills.', '2027-01-11', '2027-06-30', '2026-08-10', '2026-11-27', 15, 0, 'Pretoria', 'gauteng', 'on_site', 'active', 1, NULL, NULL, NULL, '2026-08-09 20:00:06', '2026-11-02 05:50:26'),
