INSERT INTO `opportunities` (`id`, `programme_id`, `cohort_id`, `title`, `type`, `organisation`, `short_description`, `full_description`, `application_open_date`, `application_close_date`, `start_date`, `end_date`, `available_positions`, `applications_count`, `min_age`, `max_age`, `province`, `city`, `physical_location`, `work_arrangement`, `status`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 1, NULL, 'Software Developer Intern', 'graduate_programme', 'Investhood IT (Pty) Ltd', 'Entry-level opportunity for an aspiring software developer to gain practical experience in web application development, databases, software testing, and version control while working alongside experienced developers.', 'We are looking for a motivated and enthusiastic Software Developer Intern to join our development team. The successful candidate will gain hands-on experience in designing, developing, testing, and maintaining software applications. This opportunity is ideal for a recent graduate or aspiring developer looking to strengthen their technical skills and gain exposure to professional software development practices.', '2026-08-03', '2026-09-10', '2026-10-01', '2028-09-30', 10, 0, 18, 35, 'gauteng', 'Pretoria', '12 Tech Park, Pretoria', 'hybrid', 'published', 1, '2026-08-09 15:39:50', '2026-09-08 09:52:01'),
(2, 2, NULL, 'IT Technical Support Intern', 'graduate_programme', 'Investhood IT (Pty) Ltd', 'Entry-level opportunity for an aspiring IT professional to gain hands-on experience in technical support, hardware and software troubleshooting, system administration, networking, and end-user support.', 'We are seeking a motivated and customer-focused IT Support & Technical Services Intern to join our IT team. The intern will assist with providing technical support to users, troubleshooting hardware and software issues, maintaining IT equipment, and supporting the day-to-day operation of IT systems.\r\n\r\nThis programme provides practical exposure to IT support operations while allowing the intern to develop technical, communication, problem-solving, and customer-service skills under the guidance of experienced IT professionals.', '2026-08-03', '2026-09-06', '2026-10-07', NULL, 10, 0, 18, 35, 'gauteng', 'Pretoria', '12 Tech Park, Pretoria', 'on_site', 'published', 1, '2026-08-09 16:11:29', '2026-09-04 21:58:44'),
(3, 3, NULL, 'Software Developer Intern', 'wil', 'Investhood IT (Pty) Ltd', 'A Software Developer Intern opportunity for students seeking practical experience in web application development. The successful candidates will work on real-world software projects while gaining experience in frontend and backend development, databases, debugging, version control, and software development practices.', NULL, '2026-08-10', '2026-11-27', '2027-01-11', '2027-06-30', 15, 0, 18, 35, 'mpumalanga', 'Mbombela', '23 Tech Park, Mbombela', 'on_site', 'published', 1, '2026-08-09 20:21:41', '2026-11-02 05:49:35'),
(34, 35, 133, 'SEED Opportunity 01 - igital Marketing and E-Commerce Learnership', 'learnership', 'Investhood IT - Demo Employer Network', 'Synthetic opportunity for SEED-2026-01 | Digital Marketing and E-Commerce Learnership', 'A practical learnership covering digital campaigns, e-commerce operations, content planning, analytics and customer engagement.', '2026-11-15', '2027-01-15', '2027-01-01', '2028-01-28', 30, 20, 18, 35, 'Gauteng', 'Johannesburg', 'Demo training location', 'hybrid', 'published', 1, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(35, 36, 134, 'SEED Opportunity 02 - ybersecurity Operations Graduate Programme', 'graduate_programme', 'Investhood IT - Demo Employer Network', 'Synthetic opportunity for SEED-2026-02 | Cybersecurity Operations Graduate Programme', 'A graduate programme introducing security operations, risk awareness, incident response, access management and security monitoring.', '2026-11-15', '2027-01-15', '2027-02-01', '2028-02-28', 30, 20, 18, 35, 'Gauteng', 'Johannesburg', 'Demo training location', 'hybrid', 'published', 1, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(36, 37, 135, 'SEED Opportunity 03 - ata Analytics and Business Intelligence Programme', 'skills_development', 'Investhood IT - Demo Employer Network', 'Synthetic opportunity for SEED-2026-03 | Data Analytics and Business Intelligence Programme', 'A structured programme in data preparation, SQL, spreadsheet modelling, dashboard design and business intelligence.', '2026-11-15', '2027-01-15', '2027-03-01', '2028-03-28', 30, 20, 18, 35, 'Gauteng', 'Johannesburg', 'Demo training location', 'hybrid', 'published', 1, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(37, 38, 136, 'SEED Opportunity 04 - loud Computing and DevOps Internship', 'internship', 'Investhood IT - Demo Employer Network', 'Synthetic opportunity for SEED-2026-04 | Cloud Computing and DevOps Internship', 'An internship focused on cloud fundamentals, deployment pipelines, containers, monitoring and collaborative software delivery.', '2026-11-15', '2027-01-15', '2027-04-01', '2028-04-28', 30, 20, 18, 35, 'Gauteng', 'Johannesburg', 'Demo training location', 'hybrid', 'published', 1, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(38, 39, 137, 'SEED Opportunity 05 - T Support and Network Administration Learnership', 'learnership', 'Investhood IT - Demo Employer Network', 'Synthetic opportunity for SEED-2026-05 | IT Support and Network Administration Learnership', 'A workplace-oriented learnership in service desk operations, hardware support, operating systems, networking and customer service.', '2026-11-15', '2027-01-15', '2027-05-01', '2028-05-28', 30, 20, 18, 35, 'Gauteng', 'Johannesburg', 'Demo training location', 'hybrid', 'published', 1, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(39, 40, 138, 'SEED Opportunity 06 - usiness Analysis and Project Coordination WIL', 'wil', 'Investhood IT - Demo Employer Network', 'Synthetic opportunity for SEED-2026-06 | Business Analysis and Project Coordination WIL', 'Work-integrated learning in requirements gathering, process mapping, stakeholder communication, documentation and project coordination.', '2026-11-15', '2027-01-15', '2027-06-01', '2028-06-28', 30, 20, 18, 35, 'Gauteng', 'Johannesburg', 'Demo training location', 'hybrid', 'published', 1, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(40, 41, 139, 'SEED Opportunity 07 - inancial Technology and Digital Finance Programme', 'graduate_programme', 'Investhood IT - Demo Employer Network', 'Synthetic opportunity for SEED-2026-07 | Financial Technology and Digital Finance Programme', 'A graduate programme covering digital financial services, data handling, process controls, customer onboarding and technology-enabled finance.', '2026-11-15', '2027-01-15', '2027-07-01', '2028-07-28', 30, 20, 18, 35, 'Gauteng', 'Johannesburg', 'Demo training location', 'hybrid', 'published', 1, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(41, 42, 140, 'SEED Opportunity 08 - I/UX and Product Design Internship', 'internship', 'Investhood IT - Demo Employer Network', 'Synthetic opportunity for SEED-2026-08 | UI/UX and Product Design Internship', 'An internship in user research, wireframing, prototyping, accessibility, design systems and usability evaluation.', '2026-11-15', '2027-01-15', '2027-08-01', '2028-08-28', 30, 20, 18, 35, 'Gauteng', 'Johannesburg', 'Demo training location', 'hybrid', 'published', 1, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
