INSERT INTO `programmes` (`id`, `name`, `type`, `description`, `objectives`, `duration`, `start_date`, `end_date`, `status`, `created_by`, `programme_manager_id`, `programme_officer_id`, `created_at`, `updated_at`) VALUES
(1, 'Software Development Graduate Programme', 'graduate_programme', 'A structured graduate development programme designed for recent IT and Computer Science graduates who want to gain practical experience in software development. Graduates will work alongside experienced developers on real-world projects while developing their skills in web development, databases, APIs, version control, testing, and software engineering practices.', 'Provide graduates with practical software development experience. Strengthen programming and problem-solving skills. Develop experience with modern web technologies and databases. Introduce graduates to Git and collaborative development workflows. Develop understanding of software testing, debugging, and maintenance. Encourage professional communication and teamwork. Prepare graduates for long-term careers in software development.', '24 months', '2026-10-01', '2028-09-30', 'active', 1, NULL, NULL, '2026-08-08 15:16:08', '2026-09-01 13:04:48'),
(2, 'IT Support & Technical Services Graduate Programme', 'graduate_programme', 'A graduate programme designed to provide practical experience in IT support, troubleshooting, system administration, hardware and software configuration, and user assistance. Graduates will work with IT professionals to resolve technical issues and support the organisation’s day-to-day technology operations.', 'Develop practical IT troubleshooting skills. Gain experience supporting hardware and software systems. Develop skills in diagnosing and resolving technical problems. Introduce graduates to system administration and network fundamentals. Improve customer service and communication skills. Develop knowledge of IT security and best practices. Prepare graduates for careers in IT support and technical services.', '12 months', '2026-09-07', '2027-09-30', 'active', 1, NULL, NULL, '2026-08-08 15:29:38', '2026-08-09 16:14:02'),
(3, 'Software Development Work Integrated Learning (WIL) Programme', 'wil', 'A structured Work Integrated Learning programme designed to provide students with practical workplace experience in software development. Participants will have the opportunity to apply the knowledge gained through their academic studies to real-world projects while working alongside experienced IT professionals. The programme focuses on web development, database management, software testing, version control, problem-solving, and professional workplace practices.', 'Provide students with practical experience in a professional IT environment. Apply academic knowledge to real-world software development projects. Develop practical skills in HTML, CSS, JavaScript, PHP, and MySQL. Gain experience in designing, developing, testing, and maintaining web applications. Develop database management and SQL skills. Introduce students to Git and collaborative software development workflows. Improve debugging, troubleshooting, and problem-solving abilities. Develop professional communication, teamwork, and time-management skills. Prepare students for entry-level careers in software development and IT.', '6 months', '2027-01-11', '2027-06-30', 'active', 1, NULL, NULL, '2026-08-08 15:35:07', '2026-08-08 17:14:12'),
(4, 'Software Development Graduate Programme (Copy) 2026', 'graduate_programme', 'A structured graduate development programme designed for recent IT and Computer Science graduates who want to gain practical experience in software development. Graduates will work alongside experienced developers on real-world projects while developing their skills in web development, databases, APIs, version control, testing, and software engineering practices.', 'Provide graduates with practical software development experience. Strengthen programming and problem-solving skills. Develop experience with modern web technologies and databases. Introduce graduates to Git and collaborative development workflows. Develop understanding of software testing, debugging, and maintenance. Encourage professional communication and teamwork. Prepare graduates for long-term careers in software development.', '24 months', '2026-09-01', '2028-09-29', 'paused', 1, NULL, NULL, '2026-08-08 17:14:40', '2026-09-04 22:01:02'),
(35, 'SEED-2026-01 | Digital Marketing and E-Commerce Learnership', 'learnership', 'A practical learnership covering digital campaigns, e-commerce operations, content planning, analytics and customer engagement.', 'Develop digital marketing capability, campaign execution, online merchandising and performance reporting.', '12 months', '2027-01-01', '2028-01-28', 'active', 1, 2, NULL, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(36, 'SEED-2026-02 | Cybersecurity Operations Graduate Programme', 'graduate_programme', 'A graduate programme introducing security operations, risk awareness, incident response, access management and security monitoring.', 'Build entry-level cybersecurity operations skills and responsible security practices.', '12 months', '2027-02-01', '2028-02-28', 'active', 1, 2, NULL, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(37, 'SEED-2026-03 | Data Analytics and Business Intelligence Programme', 'skills_development', 'A structured programme in data preparation, SQL, spreadsheet modelling, dashboard design and business intelligence.', 'Develop practical data analysis, reporting and evidence-based decision-making skills.', '9 months', '2027-03-01', '2028-03-28', 'active', 1, 2, NULL, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(38, 'SEED-2026-04 | Cloud Computing and DevOps Internship', 'internship', 'An internship focused on cloud fundamentals, deployment pipelines, containers, monitoring and collaborative software delivery.', 'Develop practical cloud and DevOps skills through supervised projects.', '12 months', '2027-04-01', '2028-04-28', 'active', 1, 2, NULL, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(39, 'SEED-2026-05 | IT Support and Network Administration Learnership', 'learnership', 'A workplace-oriented learnership in service desk operations, hardware support, operating systems, networking and customer service.', 'Prepare participants for entry-level IT support and network administration roles.', '12 months', '2027-05-01', '2028-05-28', 'active', 1, 2, NULL, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(40, 'SEED-2026-06 | Business Analysis and Project Coordination WIL', 'wil', 'Work-integrated learning in requirements gathering, process mapping, stakeholder communication, documentation and project coordination.', 'Apply business analysis and project coordination methods in a professional setting.', '6 months', '2027-06-01', '2028-06-28', 'active', 1, 2, NULL, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(41, 'SEED-2026-07 | Financial Technology and Digital Finance Programme', 'graduate_programme', 'A graduate programme covering digital financial services, data handling, process controls, customer onboarding and technology-enabled finance.', 'Build practical understanding of fintech operations and digital finance workflows.', '12 months', '2027-07-01', '2028-07-28', 'active', 1, 2, NULL, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(42, 'SEED-2026-08 | UI/UX and Product Design Internship', 'internship', 'An internship in user research, wireframing, prototyping, accessibility, design systems and usability evaluation.', 'Develop user-centred product design and prototyping skills.', '9 months', '2027-08-01', '2028-08-28', 'active', 1, 2, NULL, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(43, 'SEED-2026-09 | Mobile Application Development Programme', 'skills_development', 'A practical programme covering mobile application architecture, interface development, APIs, testing and release preparation.', 'Develop skills to design, build and test mobile applications.', '9 months', '2027-09-01', '2028-09-28', 'active', 1, 2, NULL, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(44, 'SEED-2026-10 | Renewable Energy Technology Support Learnership', 'learnership', 'A learnership introducing digital monitoring, technical support, data capture, safety awareness and basic renewable energy systems.', 'Develop technical support and digital operations skills for renewable energy environments.', '12 months', '2027-10-01', '2028-10-28', 'active', 1, 2, NULL, '2026-11-11 10:53:06', '2026-11-11 10:53:06'),
(45, 'SPONSOR DEMO - Youth Digital Skills Programme', 'skills_development', 'Illustrative programme for Sponsor Portal dashboards.', 'Develop practical digital skills and improve work readiness.', '12 months', '2026-10-01', '2027-09-30', 'active', 1, 2, NULL, '2026-11-12 15:15:22', '2026-11-12 15:15:22'),
(46, 'SPONSOR DEMO - Graduate Work Experience Programme', 'wil', 'Illustrative workplace experience programme for Sponsor Portal reporting.', 'Provide supervised workplace experience and support candidate progression.', '9 months', '2026-11-01', '2027-07-31', 'active', 1, 2, NULL, '2026-11-12 15:15:22', '2026-11-12 15:15:22'),
(47, 'Ai Engineer', 'learnership', 'Ai certificate', '', '3', '2026-12-01', '2027-03-31', 'active', 1, NULL, NULL, '2026-11-12 20:22:51', '2026-11-12 20:22:51'),
(48, 'Manual Software Tester', 'wil', 'Manual Testing', 'Testing Systems', '6', '2026-12-01', '2027-05-31', 'active', 1, 2, 3, '2026-11-15 13:17:43', '2026-11-15 13:17:43');
